// Saved-card / off-session charging primitives for subscription renewals.
//
// WHY THIS FILE EXISTS
// Until now a renewal could only debit the wallet (`worker/billing.ts` ->
// `debitWallet`). A customer with a perfectly good card on file was suspended the
// moment their wallet emptied, because `User.stripePaymentMethodId` was never
// written and never read. Everything needed to charge a card lives here; the
// worker owns the *policy* (when to retry, when to suspend), this module owns the
// *mechanics* (attach a card, charge it, credit the wallet for what it paid).
//
// THE MONEY MODEL — identical to checkout, deliberately
// Checkout applies wallet credit first and puts only the remainder on the card
// (`lib/wallet-split.ts`). Renewals now do the same: the card is charged the
// remainder, that exact amount is CREDITED to the wallet, and the existing
// CAS-guarded renewal transaction debits the FULL renewal from the wallet. So the
// wallet is always the thing that pays the bill and the card is always just a way
// to fund the wallet — one money path, already proven, and a partial failure can
// never half-apply a renewal.
//
// Plain server module (NOT "use server"): imported by the worker, by server
// actions and by server components. `lib/stripe.ts` is not modified by this file.

import type Stripe from "stripe";
import { db } from "./db";
import { stripe, stripeConfigured, stripePublishableKey, EMBEDDED_REQUEST_OPTS, CUSTOM_CHECKOUT_UI_MODE, type EmbeddedCheckout } from "./stripe";
import { STRIPE_MIN_CENTS } from "./wallet-split";
import { invoiceCreateData } from "./invoices";
// NOTE: no pricing imports here on purpose. `vpsTerm`, `vpsTermPriceCents` and
// `extraDiskCentsAt` were still imported after `renewalCharge` moved out to
// ./renewal-charge, leaving this file holding every ingredient of the renewal
// formula and nothing that used them — an invitation to write the second copy that
// lib/renewal-quote.ts documents two incidents about. The one formula lives in
// ./renewal-charge and is re-exported below.

/* ------------------------------------------------------------------ *
 * Small shared helpers
 * ------------------------------------------------------------------ */

function appBase(): string {
  return process.env.APP_URL ?? "http://localhost:3000";
}

/** Audit actions used to decide whether an unclaimed Stripe card may be adopted. */
export const CARD_SETUP_STARTED = "card.setup_started";
export const CARD_REMOVED = "card.removed";
export const CARD_SET_PRIMARY = "card.set_primary";

/** How long a "I clicked Add card" intent stays good for the adoption backstop. */
const SETUP_INTENT_TTL_DAYS = 7;

export type CardDisplay = {
  brand: string | null;
  last4: string | null;
  expMonth: number | null;
  expYear: number | null;
};

/** "Visa ···· 4242, expires 04/28" — one formatter for UI, email and audit text. */
export function cardDisplayLabel(card: CardDisplay): string | null {
  if (!card.last4) return null;
  const brand = brandLabel(card.brand);
  const expiry =
    card.expMonth && card.expYear
      ? `, expires ${String(card.expMonth).padStart(2, "0")}/${String(card.expYear).slice(-2)}`
      : "";
  return `${brand} ···· ${card.last4}${expiry}`;
}

/** Stripe brand ids are lowercase slugs ("visa", "amex", "unionpay"). */
export function brandLabel(brand: string | null | undefined): string {
  const map: Record<string, string> = {
    visa: "Visa",
    mastercard: "Mastercard",
    amex: "American Express",
    discover: "Discover",
    diners: "Diners Club",
    jcb: "JCB",
    unionpay: "UnionPay",
    cartes_bancaires: "Cartes Bancaires",
    eftpos_au: "Eftpos",
    link: "Link",
  };
  if (!brand) return "Card";
  return map[brand] ?? brand.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * A card is valid THROUGH the last day of its expiry month, so it stops working
 * at the first instant of the following month. Getting this off by a month would
 * either nag customers a month early or warn them after the renewal already failed.
 */
export function cardExpiresAt(expMonth: number, expYear: number): Date {
  return new Date(Date.UTC(expYear, expMonth, 1));
}

/* ------------------------------------------------------------------ *
 * Renewal pricing — ONE formula, two callers
 * ------------------------------------------------------------------ */

/**
 * What a renewal costs. Lives here (rather than being copied a third time)
 * because BOTH the worker sweep and the customer-facing "settle the balance"
 * link have to quote the same number — `renewNow` and the sweep already carry
 * the comment "the two renewal paths must never disagree", and a self-service
 * pay link that quotes a different total than the sweep charges is exactly how
 * that goes wrong.
 *
 * Pure: prices are passed in so the worker can read the admin settings once per
 * sweep instead of once per server.
 */
// `renewalCharge` and its types now live in ./renewal-charge — a pure module with
// no SDK imports, so client components can price a renewal without pulling the
// Stripe SDK and nodemailer into the browser bundle. Re-exported here so every
// existing server-side importer keeps working unchanged.
export { renewalCharge, type RenewalCharge, type PricedServer } from "./renewal-charge";

/* ------------------------------------------------------------------ *
 * Stripe customer + saving a card
 * ------------------------------------------------------------------ */

import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { stripeConfigured, createTopUpPaymentSession } from "@/lib/stripe";
import { getSettingInt } from "@/lib/settings";

/** Set by `components/customer/CouponField`; read by `topUp`'s demo gateway only. */
const COUPON_COOKIE = "nxeon_coupon";

export async function POST(req: NextRequest) {
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  if (!stripeConfigured()) {
    return NextResponse.json({ error: "Stripe is not configured yet" }, { status: 400 });
  }
  const { amount } = await req.json().catch(() => ({}));
  const dollars = Number(amount);
  if (!Number.isFinite(dollars) || dollars > 5000) {
    return NextResponse.json({ error: "Amount must be $5–$5000" }, { status: 400 });
  }
  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
  const minTopup = await getSettingInt("min_topup_cents", 500);
  if (Math.round(dollars * 100) < minTopup) {
    return NextResponse.json(
      { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}` },
      { status: 400 },
    );
  }

  // A promo code must never be silently dropped at the moment money moves.
  //
  // `CouponField` stores an accepted code in this cookie for an hour, and the ONLY
  // reader is the demo gateway in `topUp`. This route charges the card and
  // `creditCheckoutSession` credits `session.amount_total` verbatim, so a bonus
  // simply cannot be added here — and Stripe's own `discounts` /
  // `allow_promotion_codes` are the wrong instrument for a wallet top-up: they
  // reduce `amount_total`, which reduces the credit by the same cents, leaving the
  // customer exactly where they started. So a cookie surviving into this path
  // (e.g. Stripe was configured after the code was accepted) would mean paying
  // full price with a code the UI said was applied — the audit's finding #8.
  //
  // Refuse, say why, and clear the cookie in the same response so the immediate
  // retry succeeds. Nothing has been charged at this point: no session exists yet.
  const staleCoupon = req.cookies.get(COUPON_COOKIE)?.value?.trim();
  if (staleCoupon) {
    const shown = staleCoupon.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 32).toUpperCase();
    const res = NextResponse.json(
      {
        error: `Promo code ${shown || "on this account"} can’t be applied to a card payment. We’ve removed it — press Add funds again to continue without it.`,
      },
      { status: 400 },
    );
    res.cookies.set({ name: COUPON_COOKIE, value: "", path: "/", maxAge: 0 });
    return res;
  }

  // Custom Checkout (ui_mode: "elements") — the SAME session shape/UI mode the
  // VPS/Hosting/Game/Email deploy wizards' Payment step uses (PaymentStep.tsx),
  // mounted here in AddFundsPaymentModal instead of Stripe's own hosted-style
  // embedded page. `createTopUpPaymentSession` attaches the payment to a Stripe
  // CUSTOMER and saves the card (off-session renewals) exactly as before — see
  // its doc comment in lib/stripe.ts for why the session carries no order/game/
  // host/email metadata key (it must classify as a plain top-up).
  const session = await createTopUpPaymentSession(user, Math.round(dollars * 100));
  return NextResponse.json(
    session ? { clientSecret: session.clientSecret, publishableKey: session.publishableKey } : { error: "Stripe didn't return a session. Please try again." },
    session ? undefined : { status: 502 },
  );
}

