35	/**
36	 * Record that the user REACHED a wizard step. De-duped per tab-session so a
37	 * component re-render / strict-mode double-mount doesn't count a step twice — the
38	 * funnel measures distinct sessions reaching each step.
39	 */
40	export function trackDeployStep(product: DeployProduct, step: string, stepIndex: number): void {
41	  if (typeof window === "undefined") return;
42	  const key = `nx_dfstep:${product}:${stepIndex}:${step}`;
43	  try {
44	    if (window.sessionStorage.getItem(key)) return;
45	    window.sessionStorage.setItem(key, "1");
46	  } catch {
47	    /* storage disabled — still emit, just without cross-render dedupe */
48	  }
49	  send({ product, step, stepIndex, type: "step" });
50	}
