import Stripe from "stripe";
import fs from "fs";
const env = fs.readFileSync("/opt/nxeon/.env", "utf8");
const key = env.split("\n").find(l => l.startsWith("STRIPE_SECRET_KEY=")).slice("STRIPE_SECRET_KEY=".length).trim();
const stripe = new Stripe(key);

const sevenDaysAgo = Math.floor(Date.now()/1000) - 7*24*3600;
let sessions = [];
let params = { created: { gte: sevenDaysAgo }, limit: 100 };
let count = 0;
for await (const s of stripe.checkout.sessions.list(params)) {
  sessions.push(s);
  count++;
  if (count >= 2000) break; // safety cap
}
console.log("total sessions fetched:", sessions.length);

function tally(keyFn) {
  const m = {};
  for (const s of sessions) {
    const k = keyFn(s);
    m[k] = (m[k]||0)+1;
  }
  return m;
}
console.log("by status:", tally(s=>s.status));
console.log("by payment_status:", tally(s=>s.payment_status));
console.log("by mode:", tally(s=>s.mode));
console.log("by ui_mode:", tally(s=>s.ui_mode));
console.log("by metadata kind (first nxeon* key present):", tally(s => {
  const md = s.metadata || {};
  const keys = Object.keys(md).filter(k=>k.startsWith("nxeon") && k!=="nxeonUserId");
  return keys.length ? keys.sort().join(",") : "topup-or-none";
}));
// day x status breakdown
const byDay = {};
for (const s of sessions) {
  const day = new Date(s.created*1000).toISOString().slice(0,10);
  byDay[day] = byDay[day] || {};
  byDay[day][s.status] = (byDay[day][s.status]||0)+1;
}
console.log("by day/status:", JSON.stringify(byDay, null, 2));

// distinct customers created count in same window (aggregate only)
let custCount = 0;
for await (const c of stripe.customers.list({ created: { gte: sevenDaysAgo }, limit: 100 })) {
  custCount++;
  if (custCount >= 2000) break;
}
console.log("customers created in 7d:", custCount);

// distinct emails is PII - skip. Just unique customer ids referenced by sessions vs total sessions
const custIds = new Set(sessions.map(s => typeof s.customer === "string" ? s.customer : s.customer?.id).filter(Boolean));
console.log("unique customer ids among these sessions:", custIds.size, "vs total sessions:", sessions.length);

// payment intents requires_action -> canceled tally (aggregate only, no PII)
let piSample = [];
for await (const pi of stripe.paymentIntents.list({ created: { gte: sevenDaysAgo }, limit: 100 })) {
  piSample.push(pi);
  if (piSample.length >= 1000) break;
}
console.log("payment intents fetched:", piSample.length);
console.log("pi by status:", tally.call(null)); 
const piStatus = {};
for (const pi of piSample) piStatus[pi.status] = (piStatus[pi.status]||0)+1;
console.log("pi status tally:", piStatus);
const piLastError = {};
for (const pi of piSample) {
  if (pi.last_payment_error) {
    const code = pi.last_payment_error.code || pi.last_payment_error.decline_code || "unknown";
    piLastError[code] = (piLastError[code]||0)+1;
  }
}
console.log("pi last_payment_error code tally:", piLastError);
EOF
